<?php
require_once $workspace.'/models/Pricing.php';require_once $workspace.'/models/DemoRequest.php';DemoRequest::migrate($conn);
check(count(Pricing::published())===3,'Three quotation tiers published by default');check(Pricing::find('basic')['price']==='80000'&&Pricing::find('advanced')['price']==='240000'&&Pricing::find('commercial')['price']==='1999','Quotation prices match supplied options');
$tiers=Pricing::all();$tiers[0]['price']='85000.50';$tiers[1]['enabled']=false;Pricing::save($tiers);check(Pricing::find('basic')['price']==='85000.50','Admin price configuration persists');check(count(Pricing::published())===2&&Pricing::find('advanced')===null,'Unpublished tier excluded');
$bad=$tiers;$bad[0]['price']='-1';reject(function()use($bad){Pricing::save($bad);},'Negative price rejected');$bad=$tiers;$bad[0]['features']=str_repeat('x',3001);reject(function()use($bad){Pricing::save($bad);},'Excess feature text rejected');check(Pricing::find('basic')['price']==='85000.50','Invalid save preserves configuration');
$input=['full_name'=>'Quotation requester','email'=>'quote@example.com','phone'=>'09123456789','business_name'=>'Test business','business_type'=>'Retail','branch_count'=>'2','message'=>'Please demonstrate','consent'=>'1','pricing_tier'=>'basic'];DemoRequest::submit($input,bin2hex(random_bytes(32)));$message=DemoRequest::recent()[0]['message'];check(strpos($message,'85,000.50')!==false&&strpos($message,'Basic Multi-Branch')!==false,'Enquiry stores server-side selected quotation snapshot');$tiers[0]['price']='90000';Pricing::save($tiers);check(DemoRequest::recent()[0]['message']===$message,'Existing enquiry quotation unaffected by price changes');$input['pricing_tier']='advanced';reject(function()use($input){DemoRequest::submit($input,bin2hex(random_bytes(32)));},'Unpublished plan cannot be submitted');

$new=['name'=>'Enterprise','price'=>'12500','billing'=>'Per year','scope'=>'Custom scope','features'=>"One feature\nAnother feature",'alternative'=>'','note'=>'','enabled'=>1];Pricing::saveTier('add','',$new);$all=Pricing::all();$added=end($all);check(count($all)===4&&strpos($added['id'],'tier-')===0,'New tier receives stable unique identifier');check(Pricing::find($added['id'])['name']==='Enterprise','New published tier appears publicly');$new['name']='Enterprise revised';$new['enabled']=0;Pricing::saveTier('edit',$added['id'],$new);check(count(Pricing::all())===4&&Pricing::find($added['id'])===null,'Editing a tier updates it without duplicating and supports draft state');reject(function()use($new){Pricing::saveTier('edit','missing',$new);},'Editing missing tier rejected');check(Pricing::all()[0]['id']==='basic','Other tier identifiers preserved');
